    {kind==='"'revenue-chart'&&<><div className=\"chart-subhead\"><span className=\"muted\">Как менялась выручка за период</span><div className=\"segmented\">{[['days','По дням'],['weeks','По неделям']].map(([value,label])=><Button key={value} size=\"s\" view={chartView===value?'raised':'flat-secondary'} onClick={()=>setChartView(value)}>{label}</Button>)}</div></div><div className=\"chart-legend\"><span><i className=\"dot brand\"/>Текущий период</span>{ctx.compare&&<span><i className=\"dot previous\"/>Предыдущий период</span>}</div><div className=\"revenue-plot\"><Chart data={{chart:{margin:{top:12,right:12,bottom:4,left:0}},legend:{enabled:false},xAxis:{type:'category',categories:chartView==='days'?Array.from({length:30},(_,i)=>"'`${i+1} июн`):['"'1–7 июн','8–14 июн','15–21 июн','22–30 июн'],ticks:{pixelInterval:95}},yAxis:[{min:0,max:120, ticks:{pixelInterval:48},labels:{format:{type:'number',suffix:' тыс.'}},grid:{enabled:true}}],series:{data:[...(ctx.compare?[{type:'line' as const,name:'Предыдущий период',color:'var(--g-color-chart-comparison)',dashStyle:'Dash' as const,lineWidth:2,data:(chartView==='days'?trend.map((v,i)=>v*0.67+Math.sin(i)*7):[30,40,52,63]).map((y,x)=>({x,y:y*factor}))}]:[]),{type:'area',name:'Текущий период',color,fillColor:'var(--g-color-base-selection)',opacity:0.55,lineWidth:2.5,interpolation:{type:'monotone'},data:(chartView==='days'?trend.map((v,i)=>v+Math.sin(i*1.6)*12):[35,49,63,87]).map((y,x)=>({x,y:y*factor}))}]}}/></div></>}
    {kind==='traffic'&&<><div className=\"muted widget-subtitle\">Распределение посетителей</div><div className=\"donut-wrap\"><Chart data={{chart:{margin:0},legend:{enabled:false},series:{data:[{type:'pie',name:'Посетители',innerRadius:'76%',radius:'95%',borderWidth:4,borderColor:'var(--g-color-base-background)',dataLabels:{enabled:false},data:[{name:'Прямые переходы',value:42,color:'var(--g-color-chart-one)'},{name:'Поиск',value:32,color:'var(--g-color-chart-two)'},{name:'Социальные сети',value:18,color:'var(--g-color-chart-three)'},{name:'Другие',value:8,color:'var(--g-color-chart-four)'}]}]}}/><div className=\"donut-center\"><strong>{format(24680*factor)}</strong><span>посетителей</span></div></div><div className=\"traffic-legend\">{[['Прямые переходы','42','one'],['Поиск','32','two'],['Социальные сети','18','three'],['Другие','8','four']].map(([name,percent,tone])=><div key={name}><span><i className={"'`dot chart-${tone}`}/>{name}</span><strong>{percent}%</strong></div>)}</div></>}
